from typing import List

def max_non_adjacent_sum(nums: List[int]) -> int:
    if not nums:
        return 0
    elif len(nums) == 1:
        return nums[0]

    include = max(0, nums[0])
    exclude = 0

    for num in nums[1:]:
        new_exclude = max(exclude, include)
        include = exclude + num
        exclude = new_exclude

    return max(include, exclude)

