def factorial_tail_recursion(n, acc=1):
    # Base case: if n is 0, return the accumulated value
    if n == 0:
        return acc

    # Recursive case: multiply the accumulator by n and recurse with n-1
    else:
        return factorial_tail_recursion(n - 1, n * acc)

def longest_subarray_with_sum_zero(arr):
    # Dictionary to store the cumulative sum and its corresponding index
    sum_dict = {0: -1}
    max_length = -1
    end_index = -1
    cumulative_sum = 0

    for i in range(len(arr)):
        cumulative_sum += arr[i]

        if cumulative_sum in sum_dict:
            length = i - sum_dict[cumulative_sum]
            if length > max_length:
                max_length = length
                end_index = i
        else:
            sum_dict[cumulative_sum] = i

    if end_index == -1:
        return []
    else:
        return arr[end_index - max_length + 1:end_index + 1]

