def hex_to_decimal(hex_str: str) -> int:
    hex_str = hex_str[2:]  # Remove the '0x' prefix
    decimal_value = 0
    hex_length = len(hex_str)

    for i, char in enumerate(hex_str):
        if '0' <= char <= '9':
            digit = ord(char) - ord('0')
        else:
            digit = ord(char.upper()) - ord('A') + 10

        decimal_value += digit * (16 ** (hex_length - i - 1))

    return decimal_value

from typing import List, Tuple

def compress_binary_image(image: List[List[int]]) -> List[Tuple[int, int]]:
    compressed_image = []
    for row in image:
        current_value = None
        count = 0
        for pixel in row:
            if pixel != current_value:
                if current_value is not None:
                    compressed_image.append((current_value, count))
                current_value = pixel
                count = 1
            else:
                count += 1
        if current_value is not None:
            compressed_image.append((current_value, count))
    return compressed_image

