import heapq

class FileEntry:
    def __init__(self, file_id: int, access_count: int):
        self.file_id = file_id
        self.access_count = access_count

    def __lt__(self, other):
        if self.access_count == other.access_count:
            return self.file_id < other.file_id
        return self.access_count > other.access_count

def top_k_accessed_files(files: List[Tuple[int, int]], k: int) -> List[int]:
    if not files or k == 0:
        return []

    # Use a priority queue to keep track of the top k most accessed files
    pq = []
    for file_id, access_count in files:
        if len(pq) < k:
            heapq.heappush(pq, FileEntry(file_id, access_count))
        else:
            if access_count > pq[0].access_count or (access_count == pq[0].access_count and file_id < pq[0].file_id):
                heapq.heappop(pq)
                heapq.heappush(pq, FileEntry(file_id, access_count))

    # Extract the file IDs from the priority queue
    result = [entry.file_id for entry in sorted(pq, key=lambda x: (-x.access_count, x.file_id))]
    return result

