from typing import List

def ternary_search(arr: List[int], left: int, right: int, key: int) -> int:
    while left <= right:
        mid1 = left + (right - left) // 3
        mid2 = right - (right - left) // 3

        if arr[mid1] == key:
            return mid1
        elif arr[mid2] == key:
            return mid2
        elif key < arr[mid1]:
            right = mid1 - 1
        elif key > arr[mid2]:
            left = mid2 + 1
        else:
            left = mid1 + 1
            right = mid2 - 1

    return -1

def ternary_search_range(arr: List[int], left: int, right: int, key: int) -> int:
    # Check if the key is within the specified range
    if key < arr[left] or key > arr[right]:
        return -1

    # Perform ternary search within the specified range
    result = ternary_search(arr, left, right, key)

    return result

